import reference_impl as _ref

TABLE_SIZE = 6
MAX_TABLE_LENGTH = 0xFFFF
MIN_SPLIT_SIZE = 4


def split(data):
    data = bytes(data)
    n = len(data)
    if n < MIN_SPLIT_SIZE:
        raise ValueError("split needs at least %d bytes, got %d" % (MIN_SPLIT_SIZE, n))
    seg = n // 4
    return (data[0:seg], data[seg:2 * seg], data[2 * seg:3 * seg], data[3 * seg:])


def join(streams):
    streams = tuple(bytes(s) for s in streams)
    if len(streams) != 4:
        raise ValueError("join expects exactly 4 streams, got %d" % len(streams))
    return b"".join(streams)


def pack(streams):
    streams = tuple(bytes(s) for s in streams)
    if len(streams) != 4:
        raise ValueError("pack expects exactly 4 streams")
    table = bytearray()
    for s in streams[:3]:
        if len(s) > _ref.MAX_TABLE_LENGTH:
            raise ValueError("stream too long")
        table += len(s).to_bytes(2, "little")
    return bytes(table) + b"".join(streams)


def unpack(block):
    return tuple(s[::-1] for s in _ref.unpack(block))


def encode(data):
    return pack(split(data))


def decode(block):
    return join(unpack(block))
